data = {code: dict(zip(KEYS, vals)) for code, vals in LANGS.items()}
for code in data:
    extra = EXTRA.get(code, EXTRA["en"])
    for k, v in EXTRA["en"].items():
        data[code][k] = extra.get(k, v)
(ROOT / "_i18n_data.json").write_text(
    json.dumps(data, ensure_ascii=False, indent=1), encoding="utf-8")
print("écrit:", ROOT / "_i18n_data.json")

# 2) injecter dans app/lang/*.json
lang_dir = ROOT.parents[1] / "app" / "lang"
patched = 0
for code, block in data.items():
    p = lang_dir / f"{code}.json"
    if not p.exists():
        print("manquant:", p); continue
    d = json.loads(p.read_text(encoding="utf-8"))
    d["fichiers"] = block
    p.write_text(json.dumps(d, ensure_ascii=False, indent=1), encoding="utf-8")
    patched += 1
print(f"app/lang patchés: {patched}/24")
